    case 0x04: return "FLAME";
    case 0x02: return "SILVER";
    case 0x01: return "SHARPENING";
    case 0x10: return "PIERCING";
    case 0x80: return "EXPERIENCE";
    case 0x40: return "WILL_REGENERATION";
    case 0x20: return "HEALTH_REGENERATION";
    }
    return "";
